{
  "meta": {
    "name": "Project Manager",
    "description": "A project management tool with projects, tasks, comments, team members, and a premium tier that unlocks time tracking. Managers see analytics."
  },
  "entities": [
    {
      "name": "Project",
      "ownable": true,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "dueDate",
          "type": "date"
        },
        {
          "name": "status",
          "type": "enum",
          "enumValues": [
            "notStarted",
            "inProgress",
            "completed",
            "onHold"
          ],
          "default": "notStarted"
        }
      ]
    },
    {
      "name": "Task",
      "ownable": true,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "dueDate",
          "type": "date"
        },
        {
          "name": "status",
          "type": "enum",
          "enumValues": [
            "notStarted",
            "inProgress",
            "completed",
            "onHold"
          ],
          "default": "notStarted"
        }
      ],
      "relations": [
        {
          "name": "project",
          "kind": "manyToOne",
          "target": "Project",
          "required": true
        },
        {
          "name": "assignee",
          "kind": "manyToOne",
          "target": "User",
          "required": false
        }
      ]
    },
    {
      "name": "Comment",
      "ownable": true,
      "fields": [
        {
          "name": "text",
          "type": "text",
          "required": true
        },
        {
          "name": "timestamp",
          "type": "datetime",
          "required": true
        }
      ],
      "relations": [
        {
          "name": "task",
          "kind": "manyToOne",
          "target": "Task",
          "required": true
        },
        {
          "name": "user",
          "kind": "manyToOne",
          "target": "User",
          "required": true
        }
      ]
    },
    {
      "name": "TimeEntry",
      "ownable": true,
      "fields": [
        {
          "name": "startTime",
          "type": "datetime",
          "required": true
        },
        {
          "name": "endTime",
          "type": "datetime"
        },
        {
          "name": "duration",
          "type": "integer"
        }
      ],
      "relations": [
        {
          "name": "task",
          "kind": "manyToOne",
          "target": "Task",
          "required": true
        },
        {
          "name": "user",
          "kind": "manyToOne",
          "target": "User",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "member",
      "isDefault": true
    },
    {
      "name": "premiumMember"
    },
    {
      "name": "manager"
    }
  ],
  "permissions": [
    {
      "role": "member",
      "entity": "Project",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "member",
      "entity": "Task",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "member",
      "entity": "Comment",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "premiumMember",
      "entity": "TimeEntry",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "manager",
      "entity": "Project",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "manager",
      "entity": "Task",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "manager",
      "entity": "Comment",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "manager",
      "entity": "TimeEntry",
      "actions": [
        "read"
      ],
      "scope": "all"
    }
  ],
  "pages": [
    {
      "name": "Projects",
      "route": "/projects",
      "type": "list",
      "entity": "Project",
      "access": [
        "member",
        "premiumMember",
        "manager"
      ]
    },
    {
      "name": "New Project",
      "route": "/projects/new",
      "type": "form",
      "entity": "Project",
      "access": [
        "member",
        "premiumMember",
        "manager"
      ]
    },
    {
      "name": "Project Detail",
      "route": "/projects/:id",
      "type": "detail",
      "entity": "Project",
      "access": [
        "member",
        "premiumMember",
        "manager"
      ]
    },
    {
      "name": "Tasks",
      "route": "/tasks",
      "type": "list",
      "entity": "Task",
      "access": [
        "member",
        "premiumMember",
        "manager"
      ]
    },
    {
      "name": "New Task",
      "route": "/tasks/new",
      "type": "form",
      "entity": "Task",
      "access": [
        "member",
        "premiumMember",
        "manager"
      ]
    },
    {
      "name": "Analytics",
      "route": "/analytics",
      "type": "dashboard",
      "access": [
        "manager"
      ],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Projects",
          "entity": "Project",
          "metric": "count"
        },
        {
          "type": "stat",
          "label": "Total Tasks",
          "entity": "Task",
          "metric": "count"
        },
        {
          "type": "chart",
          "label": "Tasks by Status",
          "entity": "Task",
          "field": "status"
        }
      ]
    }
  ],
  "plans": [
    {
      "name": "free",
      "isDefault": true
    },
    {
      "name": "premium",
      "price": 10,
      "interval": "month",
      "features": [
        "timeTracking"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "timeTrackingGate",
      "requiresPlan": "premium",
      "gates": {
        "entities": [
          "TimeEntry"
        ],
        "features": [
          "timeTracking"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "projectOwnership",
      "entity": "Project"
    },
    {
      "type": "ownership",
      "id": "taskOwnership",
      "entity": "Task"
    },
    {
      "type": "ownership",
      "id": "commentOwnership",
      "entity": "Comment"
    },
    {
      "type": "ownership",
      "id": "timeEntryOwnership",
      "entity": "TimeEntry"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
